export function parseCsv(text) {
  if (text === '') return [];

  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let endedWithLineBreak = false;

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];

    if (inQuotes) {
      if (char === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 1;
        } else {
          inQuotes = false;
        }
      } else {
        field += char;
      }
      endedWithLineBreak = false;
      continue;
    }

    if (char === '"' && field === '') {
      inQuotes = true;
      endedWithLineBreak = false;
      continue;
    }

    if (char === ',') {
      row.push(field);
      field = '';
      endedWithLineBreak = false;
      continue;
    }

    if (char === '\n' || (char === '\r' && text[i + 1] === '\n')) {
      if (char === '\r') i += 1;
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      endedWithLineBreak = true;
      continue;
    }

    field += char;
    endedWithLineBreak = false;
  }

  if (!endedWithLineBreak) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}

export function toObjects(rows) {
  if (rows.length === 0) return [];

  const [header, ...body] = rows;

  return body.map((row) =>
    header.reduce((object, key, index) => {
      object[key] = index < row.length ? row[index] : '';
      return object;
    }, {}),
  );
}

