  ["", []],
  ["a,b", [["a","b"]]],
  ["a,b\n", [["a","b"]]],
  ["a,b\r\n", [["a","b"]]],
  ["a,b\r\nc,d", [["a","b"],["c","d"]]],
  ["\n", [[""]]],
  ["a\n\n", [["a"],[""]]],
  ["a,\"b,c\",d", [["a","b,c","d"]]],
  ["\"line1\nline2\",x", [["line1\nline2","x"]]],
  ["\"he said \"\"hi\"\"\",x", [["he said \"hi\"","x"]]],
  ["\"\"", [[""]]],
];
let ok = true;
for (const [input, expected] of cases) {
  const got = parseCsv(input);
  const pass = JSON.stringify(got) === JSON.stringify(expected);
  if (!pass) { ok = false; console.log("FAIL", JSON.stringify(input), "=>", JSON.stringify(got), "expected", JSON.stringify(expected)); }
}
const objs = toObjects([["a","b","c"],["1","2"],["3","4","5"]]);
const objPass = JSON.stringify(objs) === JSON.stringify([{a:"1",b:"2",c:""},{a:"3",b:"4",c:"5"}]);
if (!objPass) { ok = false; console.log("FAIL toObjects", JSON.stringify(objs)); }
console.log(ok ? "all pass" : "failures above");
